    c3 = [
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Biết ai, kẻ trung nghĩa,", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Gỡ cho, oán hận này!", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "contemplative", "text": ". ......", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-12%", "lead_in_pause": "1.50s", "timbre_eq": "contemplative_narrator"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Đổng Trác thường thường sai người đến dò ý tứ, hôm ấy có kẻ bắt được bài thơ đem trình Đổng Trác. Trác nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Dong_Trac", "character_name": "Đổng Trác", "text": "Làm bài thơ oán vọng này, đem giết đi là có cớ rồi!", "age_stage": "trung_nien", "temperament": "hach_dich_bao_nguoc", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "+3Hz", "rate": "+4%", "lead_in_pause": "0.35s", "timbre_eq": "tyrant_arrogant"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Bèn sai Lý Nho và mười võ sĩ vào cung giết vua. Vua, Thái Hậu và Đường phi đương ở trên lầu, thấy người cung nữ báo rằng có Lý Nho đến, vua sợ giật mình. Nho đem rượu thuốc độc dâng vua. Vua hỏi việc gì. Nho thưa,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.40s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Ngày xuân mát mẻ, Đổng tướng quốc sai tôi đem dâng chén rượu thọ.", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "de_doa_tham_hiem", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-3%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Thái Hậu bảo Lý Nho,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ha_Thai_Hau", "character_name": "Hà Thái Hậu", "text": "Có phải rượu thọ thì ngươi thử uống trước đi!", "age_stage": "trung_nien", "temperament": "hach_dich_bao_nguoc", "emotion": "kieu_hanh_u_uat", "voice": "vi-VN-HoaiMyNeural", "pitch": "-1Hz", "rate": "-2%", "lead_in_pause": "0.30s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Nho giận lắm, hỏi vua,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Mày không uống phải không?", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "+1%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Rồi gọi ngay tả hữu cầm con dao với tấm lụa trắng, để trước mặt vua, mà nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Rượu thọ chẳng uống. Thì phải chọn hai thứ này.", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "de_doa_tham_hiem", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-3%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Đường phi quỳ xuống nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Duong_Phi", "character_name": "Đường Phi", "text": "Thiếp xin thay vua uống chén rượu này, xin ngài để toàn mệnh cho hai mẹ con vua.", "age_stage": "thanh_xuan", "temperament": "trong_sang_thanh_thien", "emotion": "bi_kich_uat_nghen", "voice": "vi-VN-HoaiMyNeural", "pitch": "+2Hz", "rate": "-5%", "lead_in_pause": "0.32s", "timbre_eq": "youth_bright"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Lý Nho quát mắng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Mày là đứa nào, mà dám đòi chết thay vua?", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "+2%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Nho cầm chén rượu đưa cho Hà Thái Hậu và bảo rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Bà phải uống trước đi!", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "+1%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "elegiac", "text": "Hà Thái Hậu mắng nhiếc Hà Tiến là đồ vô mưu, đem giặc vào kinh đô, để có cái vạ ngày nay. Nho bức vua phải uống rượu. Vua nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-6%", "lead_in_pause": "0.38s", "timbre_eq": "elegiac_narrator"},
        {"type": "dialogue", "speaker": "Thieu_De", "character_name": "Thiếu Đế (Lưu Biện)", "text": "Hãy khoan! Để ta cùng Thái Hậu từ biệt đã.", "age_stage": "thanh_xuan", "temperament": "mem_yeu_bi_thuong", "emotion": "bi_kich_uat_nghen", "voice": "vi-VN-NamMinhNeural", "pitch": "+1Hz", "rate": "-6%", "lead_in_pause": "0.32s", "timbre_eq": "youth_bright"},
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Giời đất chao, giăng sao cũng đổ,", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Bỏ ngôi sao, ra chỗ phiên phong,", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Bởi ai nên, sự lạ lùng?", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Thieu_De", "narrative_mode": "poetic_recitation", "text": "Việc đời ngán ngẩm, ròng ròng châu tuôn.", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "elegiac", "text": "Đường phi cũng làm bài ca rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-6%", "lead_in_pause": "0.35s", "timbre_eq": "elegiac_narrator"},
        {"type": "poem", "speaker": "Duong_Phi", "narrative_mode": "poetic_recitation", "text": "Giời nghiêng, đất lại lở tan,", "voice": "vi-VN-HoaiMyNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Duong_Phi", "narrative_mode": "poetic_recitation", "text": "Phận mình thê thiếp, trái oan lạ thường!", "voice": "vi-VN-HoaiMyNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Duong_Phi", "narrative_mode": "poetic_recitation", "text": "Từ sinh, nay đã khác đường,", "voice": "vi-VN-HoaiMyNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "poem", "speaker": "Duong_Phi", "narrative_mode": "poetic_recitation", "text": "Một người một bóng, xót thương tấm lòng!", "voice": "vi-VN-HoaiMyNeural", "pitch": "-2Hz", "rate": "-18%", "lead_in_pause": "0.85s", "timbre_eq": "poetic_recitation"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Vua và Đường phi ca rồi, ôm nhau mà khóc. Lý Nho lại quát mắng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ly_Nho", "character_name": "Lý Nho", "text": "Tướng quốc đứng chờ tin! Các người dùng dằng để mong ai cứu đấy?", "age_stage": "trung_nien", "temperament": "muu_mo_nham_hiem", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "+2%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Thái Hậu thét mắng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Ha_Thai_Hau", "character_name": "Hà Thái Hậu", "text": "Thằng giặc Đổng kia! Mày hại mẹ con tao, rồi trời lại hại mày! Chúng bay cùng đảng với nhau làm điều ác, rồi chúng bay sẽ chết cả họ cho mà xem!", "age_stage": "trung_nien", "temperament": "hach_dich_bao_nguoc", "emotion": "cuong_no", "voice": "vi-VN-HoaiMyNeural", "pitch": "-1Hz", "rate": "+2%", "lead_in_pause": "0.30s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Nho tức lắm, hai tay tóm lấy Thái Hậu ném xuống dưới lầu, giết chết, lại sai võ sĩ thắt cổ Đường phi. Rót rượu độc bắt Thiếu Đế uống chết, rồi về báo Đổng Trác. Trác sai đem táng ba mẹ con ở ngoài thành. Tự bấy giờ, Trác đêm nào cũng vào cung thông dâm với các cung nữ, đêm thì lên ngủ trên sập rồng. Thường thường Trác hay đem quân ra ngoài thành. Một bữa Trác đến Dương Thành. Bấy giờ đang tháng hai, dân mở hội hát, con trai con gái tụ họp nhau xem hội rất đông.", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-5%", "lead_in_pause": "0.45s", "timbre_eq": "epic_narrator"}
    ]
    for x in c3:
        x["line_id"] = line_id
        x["chunk_id"] = 3
        items.append(x)
        line_id += 1

    # =========================================================================
    # CHUNK 4
