    c5 = [
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Các quan giật mình hỏi rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Cac_Quan", "character_name": "Quan lại / Các quan", "text": "Hôm nay là ngày sinh nhật của quan tư đồ, sao ngài lại khóc như vậy?", "age_stage": "trung_nien", "temperament": "so_hai", "emotion": "ngac_nhien", "voice": "vi-VN-NamMinhNeural", "pitch": "+1Hz", "rate": "+2%", "lead_in_pause": "0.30s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Doãn thưa rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Vuong_Doan", "character_name": "Vương Doãn", "text": "Hôm nay có phải là sinh nhật của tôi đâu! Tôi vì có một việc muốn nói với các vị, nhưng sợ Đổng Trác sinh nghi, cho nên, mượn cớ nói thác ra thế. Thằng Trác dối vua lộng quyền, xã tắc nay mai đổ mất. Đức Cao Hoàng ngày xưa đánh nhà Tần, diệt nước Sở, bao nhiêu công phu mới nên được cơ đồ này. Ngờ đâu nay mất vào tay thằng Đổng Trác. Tôi khóc là vì thế!", "age_stage": "lao_hoa", "temperament": "muu_mo_nham_hiem", "emotion": "bi_kich_uat_nghen", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-4%", "lead_in_pause": "0.35s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Các quan nghe nói cũng đều khóc cả. Trong đám ngồi có một người, vỗ tay cười ầm lên mà nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+1Hz", "rate": "+0%", "lead_in_pause": "0.35s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Các quan thử khóc từ tối đến sáng. Lại khóc từ sáng đến tối, xem có khóc chết được thằng Đổng Trác không?", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "ngao_nghe", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Doãn ngoảnh lại xem ai, thì là kiệu kỵ úy Tào Tháo, Doãn giận nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Vuong_Doan", "character_name": "Vương Doãn", "text": "Tổ tôn nhà ngươi cũng ăn lộc nhà Hán. Sao nhà ngươi không biết nghĩ cách báo quốc, lại còn cười à?", "age_stage": "lao_hoa", "temperament": "muu_mo_nham_hiem", "emotion": "cuong_no", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-3%", "lead_in_pause": "0.32s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Tôi cười, có phải cười gì đâu! Cười là các quan không biết nghĩ kế gì trừ được thằng Đổng Trác. Tháo nay tuy không có tài cán gì, nhưng xin lập tức chặt đầu thằng Đổng Trác, treo ở cửa phủ để tạ thiên hạ.", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "kieu_hung", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Doãn liền đứng dậy hỏi rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Vuong_Doan", "character_name": "Vương Doãn", "text": "Mạnh Đức có kế gì tài thế?", "age_stage": "lao_hoa", "temperament": "muu_mo_nham_hiem", "emotion": "hy_vong", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-4%", "lead_in_pause": "0.30s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Tôi lâu nay sở dĩ nép mình thờ Đổng Trác cũng là vì muốn thừa cơ giết nó. Nay nó rất tin tôi, tôi được gần nó luôn. Nghe quan tư đồ có con dao thất bảo, xin cho tôi mượn. Tôi nguyện phen này vào tận tướng phủ đâm chết thằng giặc Đổng Trác, dẫu chết cũng không oán hận gì.", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "qua_quyet", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.35s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Vương Doãn mừng lắm nói rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Vuong_Doan", "character_name": "Vương Doãn", "text": "Nếu Mạnh Đức có bụng như thế, thực là may cho thiên hạ lắm!", "age_stage": "lao_hoa", "temperament": "muu_mo_nham_hiem", "emotion": "cam_kich", "voice": "vi-VN-NamMinhNeural", "pitch": "-2Hz", "rate": "-4%", "lead_in_pause": "0.32s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Doãn thân hành rót chén rượu mời Tào Tháo. Tháo đổ rượu, cất lời thề. Doãn bèn đem dao thất bảo đưa cho. Tháo uống rượu xong, giắt dao đứng dậy đi ra. Các quan ngồi một lát rồi cũng về cả. Hôm sau Tháo giắt dao đến tướng phủ, hỏi,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.40s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Thừa tướng ở đâu?", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "tham_do", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "dialogue", "speaker": "Quan_Hau", "character_name": "Quân hầu / Gia nhân", "text": "Ở trong gác.", "age_stage": "thanh_xuan", "temperament": "xun_xoe_don_hen", "emotion": "binh_than_tu_nhien", "voice": "vi-VN-NamMinhNeural", "pitch": "-1Hz", "rate": "-2%", "lead_in_pause": "0.28s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Tháo vào, thấy Trác ngồi trên giường, Lã Bố đứng hầu bên cạnh. Trác thấy Tào Tháo, hỏi rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Dong_Trac", "character_name": "Đổng Trác", "text": "Sao hôm nay Mạnh Đức đến chậm thế?", "age_stage": "trung_nien", "temperament": "hach_dich_bao_nguoc", "emotion": "hoi_han", "voice": "vi-VN-NamMinhNeural", "pitch": "+3Hz", "rate": "+4%", "lead_in_pause": "0.32s", "timbre_eq": "tyrant_arrogant"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Thưa, ngựa tôi gầy hóa đi chậm.", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "khiem_nhuong_doi_tra", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Trác ngoảnh lại bảo Lã Bố rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Dong_Trac", "character_name": "Đổng Trác", "text": "Ta có ngựa tốt ở Tây Lương mới tiến. Phụng Tiên đi chọn một con đem lại đây cho Mạnh Đức.", "age_stage": "trung_nien", "temperament": "hach_dich_bao_nguoc", "emotion": "ban_thuong", "voice": "vi-VN-NamMinhNeural", "pitch": "+3Hz", "rate": "+4%", "lead_in_pause": "0.32s", "timbre_eq": "tyrant_arrogant"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Bố vâng lời đi lấy ngựa. Tháo thấy còn một mình Trác, bụng đã bảo dạ rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Thằng này số nó đến lúc chết đây!", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "hoi_hop_thi_thao", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.30s", "timbre_eq": "sharp_cunning"}
    ]
    for x in c5:
        x["line_id"] = line_id
        x["chunk_id"] = 5
        items.append(x)
