    c7 = [
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Quan huyện nhìn kỹ Tháo, nghĩ ngợi một lúc rồi nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Trước ta hầu quản ở Lạc Dương đã được gặp ngươi. Chính người là Tào Tháo, ngươi nói dối sao được? Lính đâu, hãy đem giam nó xuống trại, đến mai ta sẽ giải về kinh lĩnh thưởng.", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "oai_nghiem", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.35s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Quan huyện nói thế rồi cho quân canh cửa thành cơm no rượu say rồi về. Đến nửa đêm, quan huyện sai người thân tín, xuống gọi Tào Tháo lên, bảo dẫn vào nhà sau để hỏi. Tháo vào, quan huyện hỏi rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.40s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Ta nghe thừa tướng hậu đãi ngươi, sao ngươi lại chuốc lấy vạ vào thân?", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "tham_do", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.32s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Ngươi như chim sẻ biết đâu được chí chim hồng! Đã bắt được ta thì cứ đem nộp mà lấy công, hà tất phải hỏi nhiều.", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "ngao_nghe", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Quan huyện bèn đuổi cả tả hữu đi rồi bảo Tháo rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Anh đừng coi thường tôi. Tôi đây không phải là bọn tục lại đâu Cũng vì chưa gặp được chủ đấy thôi.", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "chan_thanh", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.32s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Ông cha ta, đời đời ăn lộc nhà Hán. Nếu ta không biết nghĩ cách báo quốc, có khác gì giống muông thú! Ta phải hạ mình chờ thằng Đổng Trác là muốn tìm cơ hội thuận tiện giết nó. Nay việc không xong, cũng là lòng trời!", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "khang_khai", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.35s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Quan huyện nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Mạnh Đức bây giờ định đi đâu?", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "hoi_han", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.30s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Tháo nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Ta muốn về làng, phát lời kêu gọi, vời cả chư hầu trong thiên hạ khởi binh giết Đổng Trác. Đó là sở nguyện của ta!", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "chi_khi_hao_hung", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.35s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Quan huyện nghe nói, bèn cởi trói cho Tháo, mời ngồi lên trên rồi thụp xuống lạy hai lạy mà nói rằng.", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Ông thực là người trung nghĩa ở đời này!", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "kinh_phuc", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.32s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "suspense", "text": "Tháo cũng lạy đáp lại, rồi hỏi tên họ, quan huyện nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.32s", "timbre_eq": "suspense_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Tôi họ Trần, tên Cung, tên chữ là Công Đài. Tôi có mẹ già và vợ con ở Đông Quận. Nay cảm bụng trung nghĩa của ông, xin bỏ chức quan này, theo ông đi trốn.", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "quyet_chi", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.35s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Tháo mừng lắm. Ngay đêm hôm ấy, Trần Cung thu xếp hành trang và lộ phí, cả hai người thay quần áo, mỗi người đeo một thanh gươm. Cưỡi một con ngựa, đi về quê Tào Tháo. Đi được ba hôm đến Thành Cao, trời đã xâm xẩm tối. Tháo cầm roi ngựa, trỏ vào một đám cây cối um tùm bảo Cung rằng.", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.45s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tao_Thao", "character_name": "Tào Tháo", "text": "Ở trong này có Lã Bá Sa là bạn kết nghĩa với cha tôi. Tôi muốn vào hỏi thăm tin nhà, rồi ngủ đấy một đêm, nên không?", "age_stage": "thanh_xuan", "temperament": "giao_hoat_nham_hiem", "emotion": "ban_bac", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "+0%", "lead_in_pause": "0.32s", "timbre_eq": "sharp_cunning"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Cung nói,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.30s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "Tran_Cung", "character_name": "Trần Cung", "text": "Thế thì hay lắm!", "age_stage": "thanh_xuan", "temperament": "anh_hung_hao_sang", "emotion": "dong_tinh", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-2%", "lead_in_pause": "0.28s", "timbre_eq": "warm_authority"},
        {"type": "narrator", "speaker": "Narrator", "narrative_mode": "epic", "text": "Hai người đến cửa trại xuống ngựa vào chào Lã Bá Sa, Sa hỏi Tháo rằng,", "voice": "vi-VN-NamMinhNeural", "pitch": "+0Hz", "rate": "-5%", "lead_in_pause": "0.35s", "timbre_eq": "epic_narrator"},
        {"type": "dialogue", "speaker": "La_Ba_Sa", "character_name": "Lã Bá Sa", "text": "Ta nghe triều đình tầm nã anh gấp lắm. Cha anh phải lánh sang ở Trần Lưu rồi. Sao anh đến được đây?", "age_stage": "lao_hoa", "temperament": "trong_sang_thanh_thien", "emotion": "ngac_nhien_lo_lang", "voice": "vi-VN-NamMinhNeural", "pitch": "-3Hz", "rate": "-5%", "lead_in_pause": "0.32s", "timbre_eq": "aged_gravel"}
    ]
    for x in c7:
        x["line_id"] = line_id
        x["chunk_id"] = 7
